import { spawn } from 'node:child_process';
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'], {env:{...process.env, GBRAIN_HOME:'/harness-state'}, stdio:['pipe','pipe','pipe']});
let buf=''; const pending=new Map();
p.stderr.on('data',d=>process.stderr.write(d));
p.stdout.on('data',d=>{buf+=d; let i; while((i=buf.indexOf('\n'))>=0){const line=buf.slice(0,i);buf=buf.slice(i+1); if(!line.trim())continue; let m; try{m=JSON.parse(line)}catch{continue}
 if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)} }});
let id=1;
const rpc=(method,params)=>new Promise(res=>{const myid=id++;pending.set(myid,res);p.stdin.write(JSON.stringify({jsonrpc:'2.0',id:myid,method,params})+'\n')});
const notify=(method,params)=>p.stdin.write(JSON.stringify({jsonrpc:'2.0',method,params})+'\n');
const r1=await rpc('initialize',{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'probe',version:'1'}});
console.log('INIT:',r1.result?.serverInfo?.name, r1.result?.serverInfo?.version);
notify('notifications/initialized',{});
const t=await rpc('tools/list',{});
console.log('TOOLS:',t.result.tools.map(x=>x.name).join(','));
const rem=await rpc('tools/call',{name:'remember',arguments:{fact:'MCP round-trip check marker mcp-check-2026-11-18 via stdio',content_origin:'user_said',provenance:'install-check'},_meta:{hot_memory:'off'}});
console.log('REMEMBER:',JSON.stringify(rem.result?.structuredContent??rem.result).slice(0,600));
const rec=await rpc('tools/call',{name:'recall',arguments:{query:'mcp-check-2026-11-18'},_meta:{hot_memory:'off'}});
const txt=JSON.stringify(rec.result?.structuredContent??rec.result);
console.log('RECALL has marker:', txt.includes('mcp-check-2026-11-18'));
console.log('RECALL:',txt.slice(0,700));
p.kill();
process.exit(0);
EOF
